/**
 * LDraw part library (Phase 3).
 *
 * `parts-meta.json` is generated by tools/pack-ldraw.mjs from the official LDraw parts library
 * (CC BY 2.0, www.ldraw.org): each part's name, bounding box (LDraw units, −Y up) and the
 * position and direction of every stud. From it we derive grid footprints, stud points and the
 * transform between LDraw's coordinate system and the engine's.
 *
 * Units: LDU (LDraw unit). 1 stud = 20 LDU, 1 plate = 8 LDU, 1 brick = 24 LDU.
 * Engine scene units: 1 = one stud, y up. So scene = (x, −y, z) / 20.
 */
import * as THREE from "three";
import rawMeta from "./parts-meta.json";
import type { PartCategory, PartDef } from "../parts";
import type { Vec3 } from "../units";

export interface LdMeta {
  file?: string;
  name: string;
  category: string | null;
  min: [number, number, number];
  max: [number, number, number];
  /** [x, y, z, dx, dy, dz] in LDU, direction = the way the stud points */
  studs: number[][];
}

const META = rawMeta as unknown as Record<string, LdMeta> & { __colours: Record<string, { name: string; hex: string; alpha: number }> };

export const LDRAW_COLOURS = META.__colours;

export function ldMeta(id: string): LdMeta | undefined {
  if (id === "__colours") return undefined;
  return (META as Record<string, LdMeta>)[id];
}

export function hasLdraw(id: string): boolean {
  return !!ldMeta(id);
}

const snap = (v: number, step: number) => Math.round(v / step) * step;

export interface LdFootprint {
  x0: number;
  x1: number;
  z0: number;
  z1: number;
  /** LDU y of the body's top (stud bases) and bottom */
  top: number;
  bottom: number;
}

/** Footprint snapped to the half-stud grid (ignores small protrusions such as side studs). */
export function ldFootprint(id: string): LdFootprint {
  const m = ldMeta(id);
  if (!m) throw new Error(`No LDraw data for part "${id}"`);
  const up = m.studs.filter((s) => s[4] < -0.9);
  const top = up.length ? Math.min(...up.map((s) => s[1])) : snap(m.min[1], 4);
  let x0 = snap(m.min[0], 10);
  let x1 = snap(m.max[0], 10);
  let z0 = snap(m.min[2], 10);
  let z1 = snap(m.max[2], 10);
  if (x1 <= x0) x1 = x0 + 10;
  if (z1 <= z0) z1 = z0 + 10;
  return { x0, x1, z0, z1, top, bottom: Math.max(top + 4, snap(m.max[1], 4)) };
}

function categoryOf(name: string): PartCategory {
  const n = name.replace(/^[~=_]/, "");
  if (/^Brick\s+\d/.test(n) && !/with|Round|Curved|Arch/.test(n)) return "brick";
  if (/^Plate\s+\d/.test(n) && !/with|Round/.test(n)) return "plate";
  if (/^Tile/.test(n)) return "tile";
  if (/^Slope|Wedge|Curved|Bow/.test(n)) return "slope";
  if (/^Panel/.test(n)) return "panel";
  if (/Arch/.test(n)) return "arch";
  if (/Round|Dish|Dome|Cylinder|Turntable/.test(n)) return "round";
  if (/Bracket|Studs? on|Side Stud/.test(n)) return "snot";
  if (/^Brick/.test(n)) return "brick";
  if (/^Plate/.test(n)) return "plate";
  return "special";
}

const defCache = new Map<string, PartDef>();

/** A grid PartDef for any part in the LDraw pack. */
export function ldPartDef(id: string): PartDef {
  const hit = defCache.get(id);
  if (hit) return hit;
  const m = ldMeta(id);
  if (!m) throw new Error(`Unknown part "${id}"`);
  const f = ldFootprint(id);
  const w = (f.x1 - f.x0) / 20;
  const d = (f.z1 - f.z0) / 20;
  const h = Math.max(1, Math.round((f.bottom - f.top) / 8));
  const studPts: [number, number][] = m.studs
    .filter((s) => s[4] < -0.9 && Math.abs(s[1] - f.top) < 1)
    .map((s) => [(s[0] - f.x0) / 20, (s[2] - f.z0) / 20]);
  const def: PartDef = {
    id,
    ldraw: m.file ?? `${id}.dat`,
    name: m.name.replace(/\s+/g, " ").replace(/^[~=_]/, "").trim(),
    category: categoryOf(m.name),
    w,
    d,
    h,
    studs: "custom",
    studPoints: studPts,
    shape: "ldraw",
  };
  defCache.set(id, def);
  return def;
}

/** Grid-convention coordinates (footprint centred in x/z, bottom at y = 0) of the LDraw origin. */
export function gridOriginOffset(id: string): Vec3 {
  const f = ldFootprint(id);
  return [-(f.x0 + f.x1) / 2 / 20, f.bottom / 20, -(f.z0 + f.z1) / 2 / 20];
}

// ── poses ───────────────────────────────────────────────────────────────────

/** An LDraw placement: position (LDU) followed by the 3×3 rotation rows a…i. */
export type LdPose = [number, number, number, number, number, number, number, number, number, number, number, number];

const S = new THREE.Matrix4().makeScale(1, -1, 1);

/** Pose → scene-space matrix that maps the LDraw part (in scene units, origin at the LDraw origin) into the frame. */
export function poseMatrix(p: LdPose): THREE.Matrix4 {
  const [x, y, z, a, b, c, d, e, f, g, h, i] = p;
  const m = new THREE.Matrix4().set(a, b, c, x / 20, d, e, f, y / 20, g, h, i, z / 20, 0, 0, 0, 1);
  return S.clone().multiply(m).multiply(S);
}

/**
 * Position + quaternion for drawing grid-convention geometry with an LDraw pose:
 * world = R' · (v − o) + p'  ⇒  position = p' − R'·o.
 */
export function poseTransform(id: string, p: LdPose): { position: Vec3; quaternion: [number, number, number, number] } {
  const m = poseMatrix(p);
  const q = new THREE.Quaternion().setFromRotationMatrix(m);
  const o = new THREE.Vector3(...gridOriginOffset(id)).applyQuaternion(q);
  const t = new THREE.Vector3().setFromMatrixPosition(m).sub(o);
  return { position: [t.x, t.y, t.z], quaternion: [q.x, q.y, q.z, q.w] };
}

/** Stud positions/directions of a posed part, in the frame's LDraw space. */
export function posedStuds(id: string, p: LdPose): { pos: THREE.Vector3; dir: THREE.Vector3 }[] {
  const m = ldMeta(id);
  if (!m) return [];
  const [x, y, z, a, b, c, d, e, f, g, h, i] = p;
  return m.studs.map((s) => ({
    pos: new THREE.Vector3(a * s[0] + b * s[1] + c * s[2] + x, d * s[0] + e * s[1] + f * s[2] + y, g * s[0] + h * s[1] + i * s[2] + z),
    dir: new THREE.Vector3(a * s[3] + b * s[4] + c * s[5], d * s[3] + e * s[4] + f * s[5], g * s[3] + h * s[4] + i * s[5]).normalize(),
  }));
}

/**
 * Where a posed part accepts studs: the centre of every stud cell on its underside, facing
 * down (LDraw +Y) in part space. Parts whose underside cannot take a stud simply never match.
 */
export function posedSockets(id: string, p: LdPose): { pos: THREE.Vector3; dir: THREE.Vector3 }[] {
  const f = ldFootprint(id);
  const [x, y, z, a, b, c, d, e, ff, g, h, i] = p;
  const out: { pos: THREE.Vector3; dir: THREE.Vector3 }[] = [];
  // "Down" brackets: the sockets are under the top plate (z −10..10, 8 LDU below its top),
  // not at the bottom of the hanging face.
  const down = /^Bracket.*Down/.test(ldMeta(id)?.name ?? "");
  const zs: number[] = down ? [0] : [];
  if (!down) for (let sz = f.z0 + 10; sz < f.z1; sz += 20) zs.push(sz);
  for (let sx = f.x0 + 10; sx < f.x1; sx += 20)
    for (const sz of zs) {
      const sy = down ? f.top + 8 : f.bottom;
      out.push({
        pos: new THREE.Vector3(a * sx + b * sy + c * sz + x, d * sx + e * sy + ff * sz + y, g * sx + h * sy + i * sz + z),
        dir: new THREE.Vector3(b, e, h).normalize(),
      });
    }
  return out;
}

/** Oriented body box of a posed part (LDraw space), shrunk by `inset` LDU, as centre + half axes. */
export function posedBox(id: string, p: LdPose, inset = 1): { c: THREE.Vector3; axes: THREE.Vector3[]; half: number[] } {
  const f = ldFootprint(id);
  const [x, y, z, a, b, c, d, e, ff, g, h, i] = p;
  const lc = [(f.x0 + f.x1) / 2, (f.top + f.bottom) / 2, (f.z0 + f.z1) / 2];
  return {
    c: new THREE.Vector3(a * lc[0] + b * lc[1] + c * lc[2] + x, d * lc[0] + e * lc[1] + ff * lc[2] + y, g * lc[0] + h * lc[1] + i * lc[2] + z),
    axes: [new THREE.Vector3(a, d, g), new THREE.Vector3(b, e, h), new THREE.Vector3(c, ff, i)],
    half: [(f.x1 - f.x0) / 2 - inset, (f.bottom - f.top) / 2 - inset, (f.z1 - f.z0) / 2 - inset],
  };
}
